import { useState, useEffect } from 'react';
import { Bell, Grid, Menu, X } from 'lucide-react';
import { IconButton, Badge } from '@mui/material';

export default function Header() {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [currentHash, setCurrentHash] = useState(() => window.location.hash);

  useEffect(() => {
    const handleHash = () => {
      setCurrentHash(window.location.hash);
    };
    window.addEventListener('hashchange', handleHash);
    return () => window.removeEventListener('hashchange', handleHash);
  }, []);

  return (
    <header className="sticky top-0 z-50 w-full border-b border-wytnet-border bg-white/80 backdrop-blur-md">
      <div className="mx-auto flex max-w-7xl items-center justify-between px-6 py-4">

        {/* Left Side: Brand Logo */}
        <div className="flex items-center gap-3">
          <a href="#" className="flex items-center group">
            <div className="h-8 flex items-center transition-transform duration-300 group-hover:scale-105">
              <svg width="141" height="31" viewBox="0 0 141 31" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink">
                <rect width="141" height="31" fill="url(#pattern0_1_856)" />
                <defs>
                  <pattern id="pattern0_1_856" patternContentUnits="objectBoundingBox" width="1" height="1">
                    <use xlinkHref="#image0_1_856" transform="matrix(0.000805341 0 0 0.003663 -0.000519575 0)" />
                  </pattern>
                  <image id="image0_1_856" width="1243" height="273" preserveAspectRatio="none" xlinkHref="data:image/png;base64," />
                </defs>
              </svg>
            </div>
          </a>
        </div>

        {/* Center: Desktop Navigation links */}
        <nav className="hidden md:flex items-center gap-8">
          {['Features', 'Ecosystem', 'Marketplace'].map((item) => {
            const itemHash = `#${item.toLowerCase()}`;
            const isActive = currentHash === itemHash || (item === 'Features' && !currentHash);
            return (
              <a
                key={item}
                href={itemHash}
                className={`relative text-[15px] font-medium transition-colors duration-200 group py-1.5 ${isActive ? 'text-wytnet-blue' : 'text-wytnet-body hover:text-wytnet-blue'
                  }`}
              >
                {item}
                <span className={`absolute bottom-0 left-0 h-[2px] transition-all duration-300 bg-wytnet-blue group-hover:w-full ${isActive ? 'w-full' : 'w-0'
                  }`} />
              </a>
            );
          })}
        </nav>

        {/* Right Side: Action Indicators & CTA */}
        <div className="flex items-center gap-3">
          {/* Notifications button */}
          <IconButton
            size="medium"
            className="text-wytnet-dark hover:text-wytnet-blue hover:bg-slate-100 transition-colors"
            aria-label="notifications"
          >
            <Badge variant="dot" color="primary" overlap="circular" anchorOrigin={{ vertical: 'top', horizontal: 'right' }}>
              <Bell className="h-5 w-5 text-[#2c3e50]" />
            </Badge>
          </IconButton>

          {/* Grid apps button */}
          <IconButton
            size="medium"
            className="text-wytnet-dark hover:text-wytnet-blue hover:bg-slate-100 transition-colors hidden sm:inline-flex"
            aria-label="apps grid"
          >
            <Grid className="h-5 w-5 text-[#2c3e50]" />
          </IconButton>

          {/* Start Free button */}
          <a
            href="#portal"
            className="hidden sm:inline-flex items-center justify-center rounded-full bg-wytnet-blue px-6 py-2.5 text-sm font-semibold text-white shadow-sm transition-all duration-200 hover:bg-wytnet-blue/95 hover:shadow-md hover:-translate-y-[1px] active:translate-y-0"
          >
            Start Free
          </a>

          {/* Mobile Hamburguer trigger */}
          <IconButton
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="md:hidden text-wytnet-dark"
            aria-label="toggle navigation menu"
          >
            {mobileMenuOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
          </IconButton>
        </div>
      </div>

      {/* Mobile navigation panel */}
      {mobileMenuOpen && (
        <div className="md:hidden border-t border-wytnet-border bg-white py-4 px-6 animate-fadeIn shadow-lg absolute left-0 right-0">
          <div className="flex flex-col gap-4">
            {['Features', 'Ecosystem', 'Marketplace', 'Developer', 'Pricing'].map((item) => {
              const itemHash = `#${item.toLowerCase()}`;
              const isActive = currentHash === itemHash || (item === 'Features' && !currentHash);
              return (
                <a
                  key={item}
                  href={itemHash}
                  onClick={() => setMobileMenuOpen(false)}
                  className={`text-[16px] font-medium py-2 border-b border-slate-50 transition-colors ${isActive ? 'text-wytnet-blue' : 'text-wytnet-body hover:text-wytnet-blue'
                    }`}
                >
                  {item}
                </a>
              );
            })}
            <div className="flex flex-col gap-2 pt-2">
              <a
                href="#portal"
                onClick={() => setMobileMenuOpen(false)}
                className="flex w-full items-center justify-center rounded-full bg-wytnet-blue py-3 text-sm font-semibold text-white transition-all hover:bg-wytnet-blue/95"
              >
                Start Free
              </a>
            </div>
          </div>
        </div>
      )}
    </header>
  );
}
